# Chat Attachment

**Category**: react
**URL**: https://heroui.pro/docs/react/components/chat-attachment
> Attachment previews and composer file input helpers for AI chat surfaces.


## Usage

Use `ChatAttachment` for compact file previews in messages or prompt composers. Image and video
attachments render as a square thumbnail (with the file name revealed on hover), while other file
types render as a horizontal card with a format-specific icon, file name, and size.

```tsx
"use client";

import {ArrowUp, Paperclip} from "@gravity-ui/icons";
import {useEffect, useRef, useState} from "react";

import {
  ChatAttachment,
  ChatAttachmentGroup,
  ChatAttachmentInput,
  ChatMessage,
  PromptInput,
} from "@heroui-pro/react";

type PendingAttachment = {
  id: string;
  name: string;
  size?: number;
  src?: string;
  mimeType?: string;
};

function createAttachmentId(file: File): string {
  return `${file.name}-${file.lastModified}-${
    globalThis.crypto?.randomUUID?.() ?? Math.random().toString(36).slice(2)
  }`;
}

function revokeAttachmentUrl(attachment: PendingAttachment) {
  if (attachment.src?.startsWith("blob:")) URL.revokeObjectURL(attachment.src);
}

function revokeAttachmentUrls(attachments: readonly PendingAttachment[]) {
  attachments.forEach(revokeAttachmentUrl);
}

export function Default() {
  return (
    <ChatMessage.User>
      <ChatAttachmentGroup className="mb-2">
        <ChatAttachment
          mediaType="image"
          name="screenshot.png"
          size={248_320}
          src="https://heroui-assets.nyc3.cdn.digitaloceanspaces.com/images/egg.webp"
        />
      </ChatAttachmentGroup>
      <ChatMessage.Bubble>
        <ChatMessage.Content>What is in this screenshot?</ChatMessage.Content>
      </ChatMessage.Bubble>
    </ChatMessage.User>
  );
}

export function Composer() {
  const [attachments, setAttachments] = useState<PendingAttachment[]>([]);
  const attachmentsRef = useRef<PendingAttachment[]>([]);

  useEffect(() => {
    attachmentsRef.current = attachments;
  }, [attachments]);

  useEffect(() => {
    return () => revokeAttachmentUrls(attachmentsRef.current);
  }, []);

  const handleFilesSelected = (files: File[]) => {
    setAttachments((current) => [
      ...current,
      ...files.map((file) => ({
        id: createAttachmentId(file),
        mimeType: file.type,
        name: file.name,
        size: file.size,
        src: file.type.startsWith("image/") ? URL.createObjectURL(file) : undefined,
      })),
    ]);
  };

  return (
    <PromptInput className="max-w-xl">
      <ChatAttachmentInput onFilesSelected={handleFilesSelected}>
        <ChatAttachmentInput.Dropzone
          render={(dropzoneProps) => (
            <PromptInput.Shell {...dropzoneProps}>
              <PromptInput.Content>
                {attachments.length ? (
                  <PromptInput.Attachments>
                    <ChatAttachmentGroup>
                      {attachments.map((file) => (
                        <ChatAttachment
                          key={file.id}
                          mimeType={file.mimeType}
                          name={file.name}
                          size={file.size}
                          src={file.src}
                        >
                          <ChatAttachment.Preview />
                          <ChatAttachment.Info />
                          <ChatAttachment.Remove
                            aria-label="Remove attachment"
                            onPress={() =>
                              setAttachments((current) => {
                                const removed = current.find((item) => item.id === file.id);

                                if (removed) revokeAttachmentUrl(removed);

                                return current.filter((item) => item.id !== file.id);
                              })
                            }
                          />
                        </ChatAttachment>
                      ))}
                    </ChatAttachmentGroup>
                  </PromptInput.Attachments>
                ) : null}
                <PromptInput.TextArea placeholder="Ask about your files..." />
              </PromptInput.Content>
              <PromptInput.Toolbar>
                <PromptInput.ToolbarStart>
                  <ChatAttachmentInput.Trigger
                    render={(triggerProps) => (
                      <PromptInput.Action
                        {...triggerProps}
                        aria-label="Attach file"
                        tooltip="Attach file"
                      >
                        <Paperclip className="size-4" />
                      </PromptInput.Action>
                    )}
                  />
                </PromptInput.ToolbarStart>
                <PromptInput.ToolbarEnd>
                  <PromptInput.Send aria-label="Send">
                    <ArrowUp className="size-4" />
                  </PromptInput.Send>
                </PromptInput.ToolbarEnd>
              </PromptInput.Toolbar>
            </PromptInput.Shell>
          )}
        />
      </ChatAttachmentInput>
    </PromptInput>
  );
}

export function Grouped() {
  return (
    <ChatAttachmentGroup>
      <ChatAttachment mimeType="application/pdf" name="project-brief.pdf" size={824_120} />
      <ChatAttachment mimeType="application/zip" name="design-assets.zip" size={15_204_352} />
      <ChatAttachment name="quarterly-report.xlsx" size={98_400} />
      <ChatAttachment name="notes.docx" size={42_100} />
      <ChatAttachment name="index.tsx" size={3_820} />
      <ChatAttachment
        mimeType="application/pdf"
        name="final-v2-annual-financial-summary-report.pdf"
        size={2_411_008}
      />
      <ChatAttachment
        mediaType="image"
        name="wireframe.png"
        size={512_000}
        src="https://heroui-assets.nyc3.cdn.digitaloceanspaces.com/images/egg.webp"
      />
      <ChatAttachment
        mediaType="image"
        name="screenshot.png"
        size={248_320}
        src="https://heroui-assets.nyc3.cdn.digitaloceanspaces.com/images/egg.webp"
      />
    </ChatAttachmentGroup>
  );
}

```

